## Code Example

```javascript
// Pseudo-code: decrypt per-device payload using envelope key from KMS
function decryptPayload(encryptedKey, ciphertext, kmsClient) {
  const dataKey = kmsClient.decrypt({ CiphertextBlob: encryptedKey, KeyId: 'alias/device-key' });
  // assume AES-GCM with dataKey.Plaintext
  const plaintext = decryptAESGCM(ciphertext, dataKey.Plaintext);
  return JSON.parse(plaintext);
}
```

